Translate("ptBR", "scarlet-monastery", {
	title = "Monastério Escarlate",
	sections = {
		{
			title = "Resumo",
			text = [=[O Monastério Escarlate se ergue nas alturas do nordeste das {link:tirisfal-glades}Clareiras de Tirisfal{/link}, uma grande casa de pedra cinzenta atrás de altas muralhas. Foi outrora um lugar de estudo e oração, onde o sacerdócio de {link:lordaeron}Lordaeron{/link} guardava seus livros e treinava jovens paladinos nos caminhos da {link:holy-light}Luz Sagrada{/link}. Agora é a fortaleza e o coração pulsante da {link:scarlet-crusade}Cruzada Escarlate{/link}. Seus sinos ainda tocam. Seus salões estão cheios de cruzados de vermelho, e ninguém que entre sem o tabardo da Cruzada é bem-vindo.]=],
		},
		{
			title = "Origens",
			text = [=[Nenhuma crônica registra o ano em que o Monastério foi fundado. Antes da praga, era contado entre as sedes mais orgulhosas da fé de {link:lordaeron}Lordaeron{/link}, um bastião do conhecimento escondido nas clareiras. Estudiosos vinham à sua biblioteca. Paladinos em formação estudavam em seus salões. Quando a {link:third-war}Terceira Guerra{/link} trouxe o {link:scourge}Flagelo{/link} e a {link:fall-of-lordaeron}Queda de Lordaeron{/link}, os fanáticos da Cruzada tomaram o Monastério e fizeram dele uma fortaleza. Eles acreditam que todo forasteiro pode carregar a praga, e tratam toda raça além da sua como inimiga.]=],
		},
		{
			title = "Os Dias Atuais",
			text = [=[O Monastério é o principal bastião da Cruzada em {link:tirisfal-glades}Tirisfal{/link}. Daqui ela envia suas patrulhas e mensageiros às torres das clareiras, e trava guerra contra os {link:forsaken}Renegados{/link} às portas de sua própria capital. O {link:scarlet-commander-mograine}Comandante Escarlate Mograine{/link} lidera sua guarnição. Sua verdadeira senhora é a {link:high-inquisitor-whitemane}Alta Inquisidora Whitemane{/link}, uma sacerdotisa que, dizem, ergue os caídos para lutar de novo sob seu comando. Na {link:undercity}Cidade Baixa{/link}, {link:varimathras}Varimathras{/link} quer Whitemane e seus principais tenentes mortos. Em {link:southshore}Costa Sul{/link}, {link:raleigh-the-devout}Raleigh, o Devoto{/link}, que outrora serviu aqui, quer o mesmo. Estudiosos da {link:horde}Horda{/link} e da {link:alliance}Aliança{/link} querem o que resta na biblioteca. Os Renegados querem corações, livros e vingança.]=],
		},
		{
			title = "Dentro do Monastério",
			text = [=[• {b}O Cemitério.{/b} Atrás do Monastério fica seu campo de sepulturas. Os interrogadores da Cruzada trabalham em suas criptas, e os mortos inquietos caminham entre os túmulos.
• {b}A Biblioteca.{/b} A grande biblioteca ainda guarda os velhos livros do Monastério, protegidos pelo mestre dos cães da Cruzada e por seu arcanista.
• {b}{link:kurzen-s-compound}O Arsenal{/link}.{/b} Aqui a Cruzada treina seus recrutas e arma seus guerreiros, sob o olhar de seu campeão.
• {b}A Catedral.{/b} No coração do Monastério, {link:scarlet-commander-mograine}Mograine{/link} e {link:high-inquisitor-whitemane}Whitemane{/link} guardam o santuário da Cruzada.]=],
		},
	},
})

Translate("ptBR", "scarlet-monastery-graveyard", {
	title = "Cemitério do Monastério Escarlate",
	sections = {
		{
			title = "Resumo",
			text = [=[O cemitério do Monastério jaz entre túmulos e criptas quebrados. A Cruzada não deixa seus mortos descansarem em paz aqui. Seus interrogadores fizeram das criptas um lugar de tormento, onde prisioneiros renegados sofrem até contar o que sabem, ou até que nada reste deles. Os mortos do pátio também estão inquietos. Espíritos angustiados e fantasmas vagam entre os mausoléus, e um mago de sangue morto-vivo clama por almas na cripta mais profunda. Alguns dos mortos são antigos. Outros, como o campeão caído que caminha ali, já vestiram as cores da própria Cruzada.]=],
		},
	},
})

Translate("ptBR", "scarlet-monastery-library", {
	title = "Biblioteca do Monastério Escarlate",
	sections = {
		{
			title = "Resumo",
			text = [=[A biblioteca é o que resta do antigo saber do Monastério. Suas estantes guardam obras de história, de saber e de rituais reunidas ao longo de muitos anos, e algumas são raras além de qualquer preço: uma mitologia dos titãs, um compêndio dos caídos, uma cartilha sobre os primeiros dias da ameaça dos mortos-vivos, um livro de rituais de um mago. A Cruzada usa os livros para treinar seus paladinos contra os mortos. Não deixa mais ninguém lê-los. Os rastreadores do mestre dos cães rondam os claustros externos, e o arcanista guarda o salão interno.]=],
		},
	},
})

Translate("ptBR", "scarlet-monastery-armory", {
	title = "Arsenal do Monastério Escarlate",
	sections = {
		{
			title = "Resumo",
			text = [=[O arsenal é onde a Cruzada forja seus soldados. Seus campos de treino ressoam com exercícios. Mirmidões, defensores e centuriões guardam seus salões, e as armas da Cruzada são guardadas em seus cofres. {link:herod}Herod{/link}, o Campeão Escarlate, governa aqui, e as armas da Cruzada são dele para dar. É o melhor guerreiro do Monastério, e uma multidão de jovens aprendizes o observa e espera ser chamada. É aqui que a Cruzada transforma fazendeiros enlutados e órfãos em fanáticos de vermelho.]=],
		},
	},
})

Translate("ptBR", "scarlet-monastery-cathedral", {
	title = "Catedral do Monastério Escarlate",
	sections = {
		{
			title = "Resumo",
			text = [=[A Catedral é o santuário do Monastério e a sede de seus senhores. Seus jardins e seu pátio estão repletos de monges, capelães, abades e campeões da Cruzada. Além deles, na grande capela, o {link:scarlet-commander-mograine}Comandante Escarlate Mograine{/link} espera diante do altar, e a {link:high-inquisitor-whitemane}Alta Inquisidora Whitemane{/link} espera atrás dele. Quem chega à capela raramente sai dela. Mais adiante ainda, numa câmara que poucos veem, vive um segundo Alto Inquisidor, {link:high-inquisitor-fairbanks}Fairbanks{/link}. Quem domina a Catedral domina o Monastério.]=],
		},
	},
})

Translate("ptBR", "high-inquisitor-whitemane", {
	title = "Alta Inquisidora Whitemane",
	subtitle = "Verdadeira Senhora do Monastério",
	found = "A grande capela da Catedral do Monastério Escarlate",
	hint = [=[Saiba dela pelos inimigos da Cruzada, ou procure-a na capela da Catedral.]=],
	allegiance = "Cruzada Escarlate",
	aliases = { "Whitemane" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Alta Inquisidora Whitemane é a verdadeira senhora do {link:scarlet-monastery}Monastério Escarlate{/link}. {link:scarlet-commander-mograine}Mograine{/link} lidera seus soldados, mas é a Whitemane que a Cruzada em {link:tirisfal-glades}Tirisfal{/link} obedece. Ela é uma sacerdotisa de poder temível. Cura seus campeões, protege-os, lança seus inimigos num sono profundo e dobra suas mentes à sua vontade. O mais temido de tudo é seu dom sobre a própria morte. Quando seus guerreiros caem, ela os ergue de novo para lutar em seu nome.]=],
		},
		{
			title = "Importância",
			text = [=[Whitemane é a chefe da inquisição da Cruzada em {link:tirisfal-glades}Tirisfal{/link}. Seus inquisidores procuram a praga em todos que encontram, e a acham onde quer que olhem. Sob seu governo, o Monastério se tornou um lugar onde homens e mulheres inocentes eram torturados por não usarem o tabardo da Cruzada. Para os {link:forsaken}Renegados{/link}, ela é a principal inimiga à sua porta. Para os vivos que outrora serviram à Cruzada, ela é a prova de quão baixo a Cruzada caiu.]=],
		},
		{
			title = "Feitos",
			text = [=[• Mantém o Monastério para a {link:scarlet-crusade}Cruzada Escarlate{/link}, com {link:scarlet-commander-mograine}Mograine{/link} a seu lado.
• Governa uma inquisição que trata todo forasteiro como portador da praga.
• Invoca a Luz para golpear seus inimigos, para curar e para proteger.
• Ergue seu campeão caído da morte para lutar de novo.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Nenhuma crônica destes dias registra a vida de Whitemane antes da Cruzada, o ano em que ela se tornou Alta Inquisidora, ou onde aprendeu seu poder sobre os caídos.]=],
		},
	},
	chapters = {
		{
			title = "O Espinho Mais Afiado",
			hint = [=[Ouça o que o senhor do medo da Cidade Baixa quer que se faça em Tirisfal.]=],
			text = [=[Enquanto {link:sylvanas-windrunner}a Dama Sombria{/link} vigiava o Lich Rei no norte, {link:varimathras}Varimathras{/link} voltou-se para os inimigos mais próximos de casa. Chamou a Cruzada de espinho mais afiado no flanco dos {link:forsaken}Renegados{/link}, e de formigas vermelhas que infestam as clareiras. Queria Whitemane morta, de uma vez por todas, e todos os seus principais tenentes com ela.]=],
		},
		{
			title = "O Regime Enlouquecido",
			hint = "Ouça a história do cruzado que deixou o Monastério.",
			text = [=[{link:raleigh-the-devout}Raleigh, o Devoto{/link}, serviu outrora no Monastério com orgulho. Viu seus líderes perderem o apego à verdade. Viu inocentes torturados em nome da pureza. Partiu, e passou a crer que a Cruzada não seria curada enquanto os que a lideravam vivessem. Whitemane foi o primeiro nome que ele deu. Só quando ela caísse, disse, a verdadeira causa poderia se reacender.]=],
		},
		{
			title = "Levanta-te",
			hint = "Enfrente a Alta Inquisidora em sua capela.",
			text = [=[Quando {link:scarlet-commander-mograine}Mograine{/link} cai diante de seu altar, Whitemane avança em fúria e chama aquilo de traição. Faz seus inimigos adormecerem. Depois se ajoelha sobre seu comandante e invoca a Luz, e Mograine se ergue para lutar a seu lado mais uma vez.]=],
		},
	},
	mentions = {
		{
			text = [=[Para Dentro do {link:scarlet-monastery}Monastério Escarlate{/link}]=],
		},
		{ text = "Em Nome da Luz" },
	},
	bonds = {
		{ id = "scarlet-commander-mograine", name = "Comandante Escarlate Mograine", note = "seu comandante" },
		{ id = "high-inquisitor-fairbanks", name = "Alto Inquisidor Fairbanks", note = "partilha sua patente" },
		{ id = "varimathras", name = "Varimathras", note = "a quer morta" },
		{ id = "raleigh-the-devout", name = "Raleigh, o Devoto", note = "outrora serviu sob ela" },
	},
})

Translate("ptBR", "scarlet-commander-mograine", {
	title = "Comandante Escarlate Mograine",
	subtitle = "Comandante do Monastério",
