	hint = [=[Saiba dele pelos inimigos da Cruzada, ou enfrente-o diante do altar da Catedral.]=],
	allegiance = "Cruzada Escarlate",
	aliases = { "Mograine" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Comandante Escarlate Mograine lidera a guarnição do {link:scarlet-monastery}Monastério Escarlate{/link}, uma grande hoste de guerreiros devotados à Cruzada além de qualquer razão. É um paladino da {link:holy-light}Luz Sagrada{/link}, vestido de placas e feroz em batalha. Fica diante do altar da Catedral com seus soldados ao redor, e recebe todo estranho como um infiel a ser purificado.]=],
		},
		{
			title = "Importância",
			text = [=[Mograine é a espada do Monastério, como {link:high-inquisitor-whitemane}Whitemane{/link} é sua vontade. Os monges, abades e campeões da Catedral são dele, e também a hoste que guarda seus portões. Seus soldados não são mercenários. São fanáticos que acreditam, como ele, que a praga se esconde em cada estranho, e morrerão antes de ceder um único salão. Ele luta com toda a força de um cavaleiro da Luz, a mesma Luz que os paladinos de {link:lordaeron}Lordaeron{/link} outrora levaram contra o {link:scourge}Flagelo{/link}. Essa força agora serve a uma ordem que tortura inocentes. Os inimigos da Cruzada, vivos e mortos, o apontam entre os primeiros que precisam cair. Para os {link:forsaken}Renegados{/link}, é um fanático a ser abatido. Para {link:raleigh-the-devout}Raleigh, o Devoto{/link}, que outrora serviu sob ele, é um dos homens que desviaram a Cruzada.]=],
		},
		{
			title = "Feitos",
			text = [=[• Comanda a guarnição do {link:scarlet-monastery}Monastério Escarlate{/link}.
• Luta envolto na aura da retribuição, e golpeia como um cruzado da Luz.
• Quando está perto da morte, pode invocar a Luz para curar-se de todas as feridas.
• Luta ao lado de {link:high-inquisitor-whitemane}Whitemane{/link}, que pode erguê-lo quando ele cai.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Nenhuma crônica destes dias registra o nome de batismo de Mograine, seus feitos antes da Cruzada, ou como ele veio a comandar o Monastério.]=],
		},
	},
	chapters = {
		{
			title = "Seu Alto Escalão",
			hint = [=[Ouça o que o senhor do medo da Cidade Baixa quer que se faça em Tirisfal.]=],
			text = [=[{link:varimathras}Varimathras{/link} não queria apenas {link:high-inquisitor-whitemane}Whitemane{/link}. Queria também os líderes ao redor dela eliminados, e nomeou Mograine primeiro entre eles: um fanático a ser abatido em seu próprio santuário.]=],
		},
		{
			title = "O Comandante Cai",
			hint = "Ouça a história do cruzado que deixou o Monastério.",
			text = [=[Para {link:raleigh-the-devout}Raleigh, o Devoto{/link}, Mograine era um dos mais altos oficiais de um regime enlouquecido. Enquanto tais homens dominassem o Monastério, dizia, qualquer um que cruzasse o caminho da Cruzada estaria em perigo.]=],
		},
		{
			title = "Diante do Altar",
			hint = "Enfrente o comandante na grande capela da Catedral.",
			text = [=[Mograine recebe os invasores no altar e os chama de infiéis. Quando ele cai, a Alta Inquisidora vem vingá-lo. Ela não o deixa ficar morto. Erguido por sua mão, ele se levanta e volta a seu lado.]=],
		},
	},
	mentions = {
		{
			text = [=[Para Dentro do {link:scarlet-monastery}Monastério Escarlate{/link}]=],
		},
		{ text = "Em Nome da Luz" },
	},
	bonds = {
		{ id = "high-inquisitor-whitemane", name = "Alta Inquisidora Whitemane", note = "sua senhora" },
		{ id = "herod", name = "Herod", note = "campeão do Monastério" },
		{ id = "varimathras", name = "Varimathras", note = "o quer morto" },
		{ id = "raleigh-the-devout", name = "Raleigh, o Devoto", note = "o quer morto" },
	},
})

Translate("ptBR", "herod", {
