	sections = {
		{
			title = "Resumo",
			text = [=[O Alto Inquisidor Fairbanks vive na {link:scarlet-monastery-cathedral}Catedral do Monastério Escarlate{/link}, numa câmara além da capela onde {link:high-inquisitor-whitemane}Whitemane{/link} mantém sua corte. Poucos sabem que ele está ali. Ele tem a mesma patente de Whitemane, o título de Alto Inquisidor, e no entanto é ela quem governa o Monastério, e ele quem é mantido fora de vista. É pálido como um cadáver, e sua voz é a voz oca dos mortos.]=],
		},
		{
			title = "Importância",
			text = [=[Fairbanks é um enigma no coração da Cruzada. No Monastério, apenas {link:high-inquisitor-whitemane}Whitemane{/link} tem o mesmo título. A Cruzada queima os mortos-vivos onde quer que os encontre, e ainda assim um Alto Inquisidor com aparência de morto vive em seu próprio santuário. Ele é, mesmo assim, um sacerdote de grande habilidade. Protege-se e cura-se, lança uma maldição de sangue sobre seus inimigos, faz com que adormeçam e os afugenta em terror.]=],
		},
		{
			title = "Feitos",
			text = [=[• Tem a patente de Alto Inquisidor da Cruzada.
• Mantém-se numa câmara à parte, além do altar da Catedral.
• Amaldiçoa, aterroriza e adormece seus inimigos, e cura as próprias feridas.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Nenhuma crônica destes dias registra quem Fairbanks foi, por que partilha a patente de {link:high-inquisitor-whitemane}Whitemane{/link}, ou por que é mantido escondido do resto do Monastério.]=],
		},
	},
	chapters = {
		{
			title = "A Câmara Além",
			hint = "Encontre o inquisidor que espera além da capela.",
			text = [=[Depois do altar onde {link:scarlet-commander-mograine}Mograine{/link} e {link:high-inquisitor-whitemane}Whitemane{/link} caíram há uma porta, e depois da porta espera Fairbanks. Ele luta sozinho, sem guardas e sem a hoste que serve a Mograine. O que ele sabe da Cruzada, e por que ela o mantém escondido, ele guarda para si. Quem deixa sua câmara leva consigo apenas mais perguntas.]=],
		},
	},
	bonds = {
		{ id = "high-inquisitor-whitemane", name = "Alta Inquisidora Whitemane", note = "partilha sua patente" },
	},
})

